<?php
namespace App\Http\Controllers\Api\Accounting;
use App\Http\Controllers\Controller; use App\Models\Accounting\JournalLine; use Illuminate\Http\Request;
class GeneralLedgerController extends Controller { public function index(Request $r) { $d=$r->validate(['start_date'=>'nullable|date','end_date'=>'nullable|date','account_id'=>'nullable|exists:chart_of_accounts,id','project_id'=>'nullable|exists:projects,id','donor_id'=>'nullable|exists:donors,id','department_id'=>'nullable|exists:departments,id']); $q=JournalLine::with(['journal:id,journal_number,journal_date,reference,description,status','account:id,code,name'])->whereHas('journal',fn($x)=>$x->where('status','posted'))->when($d['start_date']??null,fn($x,$v)=>$x->whereHas('journal',fn($j)=>$j->whereDate('journal_date','>=',$v)))->when($d['end_date']??null,fn($x,$v)=>$x->whereHas('journal',fn($j)=>$j->whereDate('journal_date','<=',$v)))->when($d['account_id']??null,fn($x,$v)=>$x->where('account_id',$v))->when($d['project_id']??null,fn($x,$v)=>$x->where('project_id',$v))->when($d['donor_id']??null,fn($x,$v)=>$x->where('donor_id',$v))->when($d['department_id']??null,fn($x,$v)=>$x->where('department_id',$v))->orderBy('journal_id')->orderBy('line_order'); $rows=$q->get(); $balance=0; $data=$rows->map(function($l)use(&$balance){$balance+=(float)$l->debit-(float)$l->credit;return ['id'=>$l->id,'date'=>$l->journal->journal_date?->toDateString(),'journal_number'=>$l->journal->journal_number,'reference'=>$l->journal->reference,'account_code'=>$l->account->code,'account_name'=>$l->account->name,'description'=>$l->line_description,'debit'=>$l->debit,'credit'=>$l->credit,'running_balance'=>round($balance,2)];}); return response()->json(['success'=>true,'data'=>$data,'totals'=>['debit'=>$rows->sum('debit'),'credit'=>$rows->sum('credit'),'closing_balance'=>$balance]]); } }
